insert into public.material_catalog_supplier_prices (
  item_id,
  supplier_id,
  supplier_name_snapshot,
  product_url,
  unit_price,
  availability,
  notes,
  price_observed_at,
  updated_at
)
select
  item.id,
  snapshot.supplier_id,
  snapshot.supplier_name,
  snapshot.product_url,
  snapshot.unit_price,
  case when snapshot.unit_price is null then 'unknown' else 'available' end,
  case
    when snapshot.unit_price is null then 'Verified exact retailer product page. Price was not published without a store selection.'
    else 'Verified exact retailer product page and public website price snapshot.'
  end,
  case when snapshot.unit_price is null then null else now() end,
  now()
from product_snapshot snapshot
join public.material_catalog_items item on item.item_code = snapshot.item_code
on conflict (item_id, supplier_id) do update
set supplier_name_snapshot = excluded.supplier_name_snapshot,
    product_url = excluded.product_url,
    unit_price = coalesce(excluded.unit_price, material_catalog_supplier_prices.unit_price),
    availability = case
      when excluded.unit_price is null then material_catalog_supplier_prices.availability
      else excluded.availability
    end,
    notes = excluded.notes,
    price_observed_at = case
      when excluded.unit_price is null then material_catalog_supplier_prices.price_observed_at
      else excluded.price_observed_at
    end,
    updated_at = now();

with catalog_images(item_code, image_url) as (
