update public.material_catalog_items item
set image_url = images.image_url,
    updated_at = now()
from catalog_images images
where item.item_code = images.item_code
  and item.image_url is null;

update public.material_catalog_items
set name = case item_code
  when 'FLO-001' then '3-1/4 in. oak hardwood flooring'
  when 'FLO-004' then '6-mil polyethylene vapor barrier, 10 x 100 ft.'
  when 'SHR-009' then 'Drywall sanding sponge, medium grit'
  when 'SHR-010' then '20-minute setting-type joint compound, 18 lb.'
  when 'SID-001' then 'White double 4 in. vinyl siding panel'
  when 'SID-012' then '1-1/2 in. siding nails'
  when 'TIL-001' then '12 x 24 in. porcelain floor tile'
  when 'TIL-011' then 'Reusable tile leveling wedges, 100-count'
  when 'WIN-001' then '36 x 60 in. double-hung window'
  when 'WIN-002' then '32 x 62 in. double-hung window'
  when 'WIN-003' then '28 x 54 in. double-hung window'
  when 'WIN-004' then '48 x 48 in. picture window'
  else name
end,
updated_at = now()
where item_code in ('FLO-001', 'FLO-004', 'SHR-009', 'SHR-010', 'SID-001', 'SID-012', 'TIL-001', 'TIL-011', 'WIN-001', 'WIN-002', 'WIN-003', 'WIN-004');
